pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0) && rewardToken != address(c));
        // Add reward token once
        c.addReward(rewardToken);
        // Try adding the same reward token again – should revert in reference
        bool reverted = false;
        try c.addReward(rewardToken) {
            // succeeded
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

